#include <iostream>
#include <random>
#include <vector>
#include <stdexcept>

std::vector<int> generar(std::mt19937& motor, int cantidad,
                         int minimo, int maximo) {
    if (cantidad < 0 || cantidad > 20 || minimo < -12 || minimo > 12
            || maximo < -12 || maximo > 12 || minimo > maximo) {
        throw std::invalid_argument("Configuracion invalida");
    }
    std::uniform_int_distribution<int> elegir{minimo, maximo};
    std::vector<int> datos;
    for (int i{0}; i < cantidad; ++i) {
        datos.push_back(elegir(motor));
    }
    return datos;
}

int main() {
    std::mt19937 por_lotes{191};
    const std::vector<int> primero = generar(por_lotes, 4, -2, 5);
    std::mt19937 continuacion = por_lotes;
    const std::vector<int> segundo = generar(por_lotes, 3, -2, 5);
    const std::vector<int> repetido = generar(continuacion, 3, -2, 5);
    std::cout << "Continuacion:" << (primero.size() == 4 && segundo == repetido) << '\n';
    const std::mt19937 antes_vacio = por_lotes;
    const std::vector<int> vacio = generar(por_lotes, 0, 2, 2);
    std::cout << "Vacio:" << vacio.size() << ':';
    std::cout << (por_lotes == antes_vacio) << '\n';
    const std::mt19937 antes_error = por_lotes;
    try {
        const std::vector<int> datos = generar(por_lotes, 3, 5, 2);
        std::cout << "Aceptado:" << datos.size();
    } catch (const std::invalid_argument&) {
        std::cout << "Rechazo:" << (por_lotes == antes_error);
    }
    return 0;
}
